import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.DfDAiEgj.js";const c=JSON.parse('{"title":"注意力","description":"","frontmatter":{},"headers":[],"relativePath":"idea/attention.md","filePath":"idea/attention.md","lastUpdated":null}'),r={name:"idea/attention.md"};function o(l,t,s,d,p,_){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="注意力" tabindex="-1">注意力 <a class="header-anchor" href="#注意力" aria-label="Permalink to &quot;注意力&quot;">​</a></h1><p>小便池里假苍蝇，溅出率降低60%。</p><ul><li>微博的小红点、发布（橙色）</li><li>淘宝里的立即购买（红色）、加入购物车（橙色）；拼多多里右下角的拼单<a href="https://www.zhihu.com/question/423119828" target="_blank" rel="noreferrer">^3</a></li><li>分类导航上下差5-10%</li></ul><h2 id="aida模型" tabindex="-1">AIDA模型 <a class="header-anchor" href="#aida模型" aria-label="Permalink to &quot;AIDA模型&quot;">​</a></h2><p>AIDA模式也称“爱达”公式，是艾尔莫·李维斯Elmo Lewis 在1898年首次提出总结的推销模式,是西方推销学中一个重要的公式，它的具体函义是指一个成功的推销员必须把顾客的注意力吸引或转变到产品上，使顾客对推销人员所推销的产品产生兴趣，这样顾客欲望也就随之产生，尔后再促使采取购买行为，达成交易。</p><p>AIDA是四个英文单词的首字母：A为Attention，即引起注意；I为Interest，即诱发兴趣；D为Desire，即刺激欲望；最后一个字母A为Action，即促成购买。</p><p>AIDA模型可以看作是用户做购买决策的整个行为过程，从引起注意到最终的购买行为的过程。</p><p>尽管AIDA模型是为线下推销场景提出的，但放在线上电商鼎盛的今天，依旧有很大的参考价值，下面，我们就来分析一下现有的线上产品是如何运用AIDA模型来辅助用户购买决策的。</p>',8)])])}const h=e(r,[["render",o]]);export{c as __pageData,h as default};
